async def _handle(self, request: Request) -> StreamResponse:
    rel_url = request.match_info["filename"]
    try:
        filename = Path(rel_url)
        if filename.anchor:
            # rel_url is an absolute name like
            # /static/\\machine_name\c$ or /static/D:\path
            # where the static dir is totally different
            raise HTTPForbidden()
        filepath = self._directory.joinpath(filename).resolve()
        if not self._follow_symlinks:
            filepath.relative_to(self._directory)
    except (ValueError, FileNotFoundError) as error:
        # relatively safe
        raise HTTPNotFound() from error
    except HTTPForbidden:
        raise
    except Exception as error:
        # perm error or other kind!
        request.app.logger.exception(error)
        raise HTTPNotFound() from error

    # on opening a dir, load its contents if allowed
    if filepath.is_dir():
        if self._show_index:
            try:
                return Response(
                    text=self._directory_as_html(filepath), content_type="text/html"
                )
            except PermissionError:
                raise HTTPForbidden()
        else:
            raise HTTPForbidden()
    elif filepath.is_file():
        return FileResponse(filepath, chunk_size=self._chunk_size)
    else:
        raise HTTPNotFound

def decode(self, data: bytes) -> bytes:
    """Decodes data.

    Decoding is done according the specified Content-Encoding
    or Content-Transfer-Encoding headers value.
    """
    if CONTENT_TRANSFER_ENCODING in self.headers:
        data = self._decode_content_transfer(data)
    if CONTENT_ENCODING in self.headers:
        return self._decode_content(data)
    return data

def _get_boundary(self) -> str:
    mimetype = parse_mimetype(self.headers[CONTENT_TYPE])

    assert mimetype.type == "multipart", "multipart/* content type expected"

    if "boundary" not in mimetype.parameters:
        raise ValueError(
            "boundary missed for Content-Type: %s" % self.headers[CONTENT_TYPE]
        )

    boundary = mimetype.parameters["boundary"]
    if len(boundary) > 70:
        raise ValueError("boundary %r is too long (70 chars max)" % boundary)

    return boundary

def generate_auth_token(user_id):
    host_list = request.host.rsplit(':')
    if len(host_list) == 1:
        host = ':'.join(host_list)
    else:
        host = ':'.join(host_list[0:-1])
    if host.startswith('127.') or host.lower() == 'localhost' or host.startswith('[::ffff:7f'):
        warning = _('PLease access calibre-web from non localhost to get valid api_endpoint for kobo device')
        return render_title_template(
            "generate_kobo_auth_url.html",
            title=_(u"Kobo Setup"),
            warning = warning
        )
    else:
        # Invalidate any prevously generated Kobo Auth token for this user.
        auth_token = ub.session.query(ub.RemoteAuthToken).filter(
            ub.RemoteAuthToken.user_id == user_id
        ).filter(ub.RemoteAuthToken.token_type==1).first()

        if not auth_token:
            auth_token = ub.RemoteAuthToken()
            auth_token.user_id = user_id
            auth_token.expiration = datetime.max
            auth_token.auth_token = (hexlify(urandom(16))).decode("utf-8")
            auth_token.token_type = 1

            ub.session.add(auth_token)
            ub.session_commit()

        books = calibre_db.session.query(db.Books).join(db.Data).all()

        for book in books:
            formats = [data.format for data in book.data]
            if not 'KEPUB' in formats and config.config_kepubifypath and 'EPUB' in formats:
                helper.convert_book_format(book.id, config.config_calibre_dir, 'EPUB', 'KEPUB', current_user.name)

        return render_title_template(
            "generate_kobo_auth_url.html",
            title=_(u"Kobo Setup"),
            kobo_auth_url=url_for(
                "kobo.TopLevelEndpoint", auth_token=auth_token.auth_token, _external=True
            ),
            warning = False
        )

