def get_epub_info(tmp_file_path, original_file_name, original_file_extension):
    ns = {
        'n': 'urn:oasis:names:tc:opendocument:xmlns:container',
        'pkg': 'http://www.idpf.org/2007/opf',
        'dc': 'http://purl.org/dc/elements/1.1/'
    }

    epub_zip = zipfile.ZipFile(tmp_file_path)

    txt = epub_zip.read('META-INF/container.xml')
    tree = etree.fromstring(txt)
    cfname = tree.xpath('n:rootfiles/n:rootfile/@full-path', namespaces=ns)[0]
    cf = epub_zip.read(cfname)
    tree = etree.fromstring(cf)

    coverpath = os.path.dirname(cfname)

    p = tree.xpath('/pkg:package/pkg:metadata', namespaces=ns)[0]

    epub_metadata = {}

    for s in ['title', 'description', 'creator', 'language', 'subject']:
        tmp = p.xpath('dc:%s/text()' % s, namespaces=ns)
        if len(tmp) > 0:
            if s == 'creator':
                epub_metadata[s] = ' & '.join(split_authors(tmp))
            elif s == 'subject':
                epub_metadata[s] = ', '.join(tmp)
            else:
                epub_metadata[s] = tmp[0]
        else:
            epub_metadata[s] = 'Unknown'

    if epub_metadata['subject'] == 'Unknown':
        epub_metadata['subject'] = ''

    if epub_metadata['description'] == u'Unknown':
        description = tree.xpath("//*[local-name() = 'description']/text()")
        if len(description) > 0:
            epub_metadata['description'] = description
        else:
            epub_metadata['description'] = ""

    lang = epub_metadata['language'].split('-', 1)[0].lower()
    epub_metadata['language'] = isoLanguages.get_lang3(lang)

    epub_metadata = parse_epub_series(ns, tree, epub_metadata)

    cover_file = parse_epub_cover(ns, tree, epub_zip, coverpath, tmp_file_path)

    if not epub_metadata['title']:
        title = original_file_name
    else:
        title = epub_metadata['title']

    return BookMeta(
        file_path=tmp_file_path,
        extension=original_file_extension,
        title=title.encode('utf-8').dec

def _load_from(self, data: bytes) -> None:
    if data.strip() == b'':
        data = XMP_EMPTY  # on some platforms lxml chokes on empty documents

    def basic_parser(xml):
        return parse(BytesIO(xml))

    def strip_illegal_bytes_parser(xml):
        return parse(BytesIO(re_xml_illegal_bytes.sub(b'', xml)))

    def recovery_parser(xml):
        parser = XMLParser(recover=True)
        return parse(BytesIO(xml), parser)

    def replace_with_empty_xmp(_xml=None):
        log.warning("Error occurred parsing XMP, replacing with empty XMP.")
        return basic_parser(XMP_EMPTY)

    if self.overwrite_invalid_xml:
        parsers: Iterable[Callable] = [
            basic_parser,
            strip_illegal_bytes_parser,
            recovery_parser,
            replace_with_empty_xmp,
        ]
    else:
        parsers = [basic_parser]

    for parser in parsers:
        try:
            self._xmp = parser(data)
        except (XMLSyntaxError if self.overwrite_invalid_xml else NeverRaise) as e:
            if str(e).startswith("Start tag expected, '<' not found") or str(
                e
            ).startswith("Document is empty"):
                self._xmp = replace_with_empty_xmp()
                break
        else:
            break

    try:
        pis = self._xmp.xpath('/processing-instruction()')
        for pi in pis:
            etree.strip_tags(self._xmp, pi.tag)
        self._get_rdf_root()
    except (Exception if self.overwrite_invalid_xml else NeverRaise) as e:
        log.warning("Error occurred parsing XMP", exc_info=e)
        self._xmp = replace_with_empty_xmp()
    return

def edit(self, item: Model, raise_exception: bool = False) -> bool:
    try:
        self.session.merge(item)
        self.session.commit()
        self.message = (as_unicode(self.edit_row_message), "success")
        return True
    except IntegrityError as e:
        self.message = (as_unicode(self.edit_integrity_error_message), "warning")
        log.warning(LOGMSG_WAR_DBI_EDIT_INTEGRITY.format(str(e)))
        self.session.rollback()
        if raise_exception:
            raise e
        return False
    except Exception as e:
        self.message = (
            as_unicode(self.general_error_message + " " + str(sys.exc_info()[0])),
            "danger",
        )
        log.exception(LOGMSG_ERR_DBI_EDIT_GENERIC.format(str(e)))
        self.session.rollback()
        if raise_exception:
            raise e
        return False

