def on_end_resource(self):
    if self._session is None:
        return
    try:
        self._session.flush()
        self._session.commit()
    except Exception:
        logger.exception('error trying to flush and commit session')
        self._session.rollback()
        self._session.expunge_all()
    finally:
        self._session.remove()

